import sys
from collections import defaultdict

def count_cyclical_isomorphic(s, queries):
    n = len(s)
    s_double = s + s
    count_map = defaultdict(int)

    def hash_substring(sub):
        return hash(sub)

    for i in range(n):
        for j in range(1, n + 1):
            if i + j <= n:
                sub = s[i:i+j]
                sub_rotated = s_double[i:i+j]
                count_map[hash(sub_rotated)] += 1

    results = []
    for q in queries:
        q_len = len(q)
        q_rotated = q + q
        result = 0
        for start in range(q_len):
            sub = q_rotated[start:start+q_len]
            result += count_map[hash(sub)]
        results.append(result // q_len)

    return results

def main():
    import sys
    input = sys.stdin.read().splitlines()
    s = input[0]
    n = int(input[1])
    queries = input[2:2+n]
    results = count_cyclical_isomorphic(s, queries)
    for res in results:
        print(res)

if __name__ == "__main__":
    main()
